package odoo

import (
	"sort"
	"strings"
)

// The surface catalog.
//
// The curated catalog (odoo19_catalog.go) is researched by hand and is the only catalog the
// governed product knows. It covers 36 of the 192 business models the core SME module set shows in
// its UI. The surface catalog covers the rest from what Odoo itself declares: each model's list and
// form views, and the business buttons of its form (odoo19_surface_catalog.gen.go, generated by
// scripts/dev/odoo-catalog-surface.py from a live surface inventory).
//
// A surface operation is deliberately second class until a person or a conformance run says
// otherwise:
//
//   - it is STANDALONE-ONLY. It is absent from Catalog() and CatalogByID, so nothing governed can
//     list, describe, authorize or route it, and an Adapter executes it only when built with
//     Surface set, which only the standalone executor (packages/odoo/direct) does;
//   - it is SURFACE_GENERATED evidence and UNVERIFIED readiness until a conformance record names it;
//   - its fields are provider-native: it has no semantic contract, so a list or describe answers in
//     Odoo's own field names, and its read projection is OptionalReadFields throughout, so an Odoo
//     without one of the fields (another series, another module set) still answers.
//
// Promoting an operation means moving it into the curated catalog, with a contract, a governance
// capability and evidence; the generator then stops emitting it.

// Odoo19EvidenceSurfaceGenerated labels an operation generated from an Odoo's UI surface. Nothing
// about it has been verified; its readiness is UNVERIFIED until a conformance record names it.
const Odoo19EvidenceSurfaceGenerated Odoo19EvidenceClass = "SURFACE_GENERATED"

// SurfaceCatalogByID indexes the surface catalog. It never contains a curated operation.
var SurfaceCatalogByID map[string]Odoo19Operation

func init() {
	// Read the curated slice itself, not CatalogByID: package variables are initialized before any
	// init function runs, whatever order the files' init functions run in.
	curated := make(map[string]bool, len(odoo19Catalog))
	for _, op := range odoo19Catalog {
		curated[op.SemanticID] = true
	}
	SurfaceCatalogByID = make(map[string]Odoo19Operation, len(odoo19SurfaceCatalog))
	for i := range odoo19SurfaceCatalog {
		op := &odoo19SurfaceCatalog[i]
		if curated[op.SemanticID] {
			panic("odoo: surface operation " + op.SemanticID + " duplicates a curated operation")
		}
		if _, duplicate := SurfaceCatalogByID[op.SemanticID]; duplicate {
			panic("odoo: surface operation " + op.SemanticID + " is generated twice")
		}
		validateRequiredModules(*op)
		op.Applicability = SurfaceApplicability{
			DirectCLI:     true,
			AERPCLI:       false,
			AERPCLIReason: "surface-generated: not governed until promoted into the curated catalog",
			Conformance:   true,
		}
		SurfaceCatalogByID[op.SemanticID] = *op
	}
}

// SurfaceCatalog returns a snapshot of the surface catalog, sorted by semantic id.
func SurfaceCatalog() []Odoo19Operation {
	out := make([]Odoo19Operation, len(odoo19SurfaceCatalog))
	copy(out, odoo19SurfaceCatalog)
	sort.Slice(out, func(i, j int) bool { return out[i].SemanticID < out[j].SemanticID })
	return out
}

// IsSurfaceOperation reports whether id names a surface operation.
func IsSurfaceOperation(id string) bool {
	_, ok := SurfaceCatalogByID[id]
	return ok
}

// lookupOperation finds an operation in the curated catalog and, only when surface is true, in the
// surface catalog too. Every governed caller passes false.
func lookupOperation(id string, surface bool) (Odoo19Operation, bool) {
	if op, ok := CatalogByID[id]; ok {
		return op, true
	}
	if surface {
		op, ok := SurfaceCatalogByID[id]
		return op, ok
	}
	return Odoo19Operation{}, false
}

// SurfaceReadCapability is the capability the governed product enforces for a surface READ
// operation: its family's (finance.records.read). The generated catalog's per-entity keys are not in
// the grantable vocabulary, and a role is given a domain of the business to read, not one list.
func SurfaceReadCapability(op Odoo19Operation) string {
	family, _, _ := strings.Cut(op.SemanticID, ".")
	return family + ".records.read"
}

// SurfaceWriteCapability is the capability the governed product enforces for a surface write,
// business action or dialog it executes: its family's (finance.records.write), as reads take
// SurfaceReadCapability.
func SurfaceWriteCapability(op Odoo19Operation) string {
	family, _, _ := strings.Cut(op.SemanticID, ".")
	return family + ".records.write"
}

// LookupGovernedOperation finds an operation the governed product executes: a curated one; a
// surface READ, under its family's read capability (SurfaceReadCapability, DEC-2026-0156); or a
// surface create, update, business action or dialog that is verified on 19.0, under its family's
// write capability (SurfaceWriteCapability, DEC-2026-0160). One of high or critical risk is admitted
// too, and runs only with a second person's approval (RequiresApproval, DEC-2026-0161). The rest of
// the surface stays standalone-only, and WhyNotGoverned says why.
func LookupGovernedOperation(id string) (Odoo19Operation, bool) {
	if op, ok := CatalogByID[id]; ok {
		return op, true
	}
	op, ok := SurfaceCatalogByID[id]
	if !ok {
		return Odoo19Operation{}, false
	}
	if op.Strategy == StrategyRead {
		op.RequiredCapability = Capability(SurfaceReadCapability(op))
		return op, true
	}
	if WhyNotGoverned(id) == "" {
		op.RequiredCapability = Capability(SurfaceWriteCapability(op))
		return op, true
	}
	return Odoo19Operation{}, false
}

// RequiresApproval reports whether the governed product runs op only after a second person approved
// the exact request (DEC-2026-0161): every operation of high or critical risk, curated or surface.
func RequiresApproval(op Odoo19Operation) bool {
	return op.Risk == RiskHigh || op.Risk == RiskCritical
}

// WhyNotGoverned says why a surface operation is not executed by the governed product, or "" when
// it is (and for an id outside the surface catalog). An unverified one is not offered to a business
// at all; deletes, prints and module installs stay with the standalone tool. A verified write of high
// risk IS governed, behind an approval (RequiresApproval).
func WhyNotGoverned(id string) string {
	op, ok := SurfaceCatalogByID[id]
	if !ok {
		return ""
	}
	switch op.Strategy {
	case StrategyRead:
		return ""
	case StrategyFieldWrite, StrategyMethodCall, StrategyWizard:
	default:
		return "a surface " + strings.ToLower(string(op.Strategy)) + " operation runs only through the standalone tool (odoo-cli)"
	}
	if readiness, _ := ReadinessOf(id); readiness != ReadinessCurrentVerified {
		return "a surface write that is not verified on 19.0 is not offered through the governed product"
	}
	return ""
}

// LookupStandaloneOperation finds an operation in either catalog, for the standalone surface.
func LookupStandaloneOperation(id string) (Odoo19Operation, bool) {
	return lookupOperation(id, true)
}
